#!/usr/bin/env bash
# ============================================================================
#  numprep bootstrap — single-file, self-extracting repository installer
#  Repo: numeric-preprocessing-pipeline (numprep 1.0.0)  |  Generated: 2026-10-18
#
#  Usage:
#    bash numprep-bootstrap.sh                 # extract into ./numeric-preprocessing-pipeline
#    bash numprep-bootstrap.sh --dest DIR      # extract into DIR/numeric-preprocessing-pipeline
#    bash numprep-bootstrap.sh --setup         # extract + venv + install + full verify
#    bash numprep-bootstrap.sh --check         # verify payload integrity only (no extraction)
#
#  The script is text-only (no binary download needed). The embedded payload is
#  a deterministic tar.gz of the whole repository INCLUDING its git history, and
#  its sha256 is baked in below — integrity is verified before extraction.
# ============================================================================
set -euo pipefail

PAYLOAD_SHA256="fb415a1dbeb634f90f5a9b6d47d1e35d9e44386178afbadd792b3be894e03d85"
REPO_NAME="numeric-preprocessing-pipeline"
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"

DEST="."
SETUP=0
CHECKONLY=0
while [ $# -gt 0 ]; do
    case "$1" in
        --dest)    DEST="${2:?--dest requires a directory}"; shift 2 ;;
        --setup)   SETUP=1; shift ;;
        --check)   CHECKONLY=1; shift ;;
        -h|--help) grep -E '^#( |$)' "$SELF" | sed 's/^# \{0,1\}//' | head -20; exit 0 ;;
        *) echo "unknown argument: $1 (see --help)" >&2; exit 2 ;;
    esac
done

command -v base64 >/dev/null 2>&1 || { echo "FATAL: base64 not found" >&2; exit 1; }
command -v tar >/dev/null 2>&1    || { echo "FATAL: tar not found" >&2; exit 1; }
command -v sha256sum >/dev/null 2>&1 || { echo "FATAL: sha256sum not found" >&2; exit 1; }

TMPDIR_BOOT="$(mktemp -d "${TMPDIR:-/tmp}/numprep-bootstrap.XXXXXX")"
trap 'rm -rf "$TMPDIR_BOOT"' EXIT

echo "==> Verifying payload integrity (sha256)…"
awk '/^__PAYLOAD__BELOW__$/{flag=1;next} flag' "$SELF" | base64 -d > "$TMPDIR_BOOT/payload.tar.gz"
ACTUAL="$(sha256sum "$TMPDIR_BOOT/payload.tar.gz" | awk '{print $1}')"
if [ "$ACTUAL" != "$PAYLOAD_SHA256" ]; then
    echo "FATAL: payload checksum mismatch — the file was corrupted in transit." >&2
    echo "  expected: $PAYLOAD_SHA256" >&2
    echo "  actual:   $ACTUAL" >&2
    echo "Re-download the bootstrap script and try again." >&2
    exit 3
fi
echo "    OK  $ACTUAL"

if [ "$CHECKONLY" = 1 ]; then
    echo "Integrity check passed — payload is intact."
    exit 0
fi

mkdir -p "$DEST"
echo "==> Extracting repository into $DEST/$REPO_NAME …"
tar -xzf "$TMPDIR_BOOT/payload.tar.gz" -C "$DEST"
REPO_DIR="$DEST/$REPO_NAME"

if [ "$SETUP" = 1 ]; then
    echo "==> Setup: creating venv and installing package + dev tooling…"
    cd "$REPO_DIR"
    python3 -m venv .venv
    # shellcheck disable=SC1091
    source .venv/bin/activate
    python -m pip install --upgrade pip --quiet
    python -m pip install -e ".[dev]" --quiet
    echo "==> Setup: running all quality gates (make verify)…"
    make verify
    echo
    echo "READY. The venv is active in THIS shell; in new shells run:"
    echo "  cd $REPO_DIR && source .venv/bin/activate"
else
    echo
    echo "Extracted at: $REPO_DIR"
    echo
    echo "Next steps:"
    echo "  cd $REPO_DIR"
    echo "  make install-dev                     # install package + tooling"
    echo "  make verify                          # ruff + mypy + 196 tests (≈90 s)"
    echo "  make synthesize && make run-local    # end-to-end demo on seeded dirty data"
    echo "  cat CHECKLIST.md                     # phase-by-phase verification plan"
    echo "Or re-run this script with --setup to do all of the above automatically."
fi
exit 0
